corpus_block("test-scales.R: oob affects position values", {
  dat <- data_frame(x = c("a", "b", "c"), y = c(1, 5, 10))
  .plot("test-scales.R: oob affects position values #1", base <- ggplot(dat, aes(x, y)) +
      geom_col() +
      annotate("point", x = "a", y = c(-Inf, Inf)))
  y_scale <- function(limits, oob = censor) {
      scale_y_continuous(limits = limits, oob = oob, expand = c(0, 0))
    }
  .plot("test-scales.R: oob affects position values #2", base + scale_y_continuous(limits = c(-0,5)))
  .plot("test-scales.R: oob affects position values #3", base + y_scale(c(0, 5), censor))
  low_censor <- cdata(base + y_scale(c(0, 5), censor))
  .plot("test-scales.R: oob affects position values #4", base + y_scale(c(3, 7), censor))
  mid_censor <- cdata(base + y_scale(c(3, 7), censor))
  handle <- GeomBar$handle_na
  .plot("test-scales.R: oob affects position values #5", base + y_scale(c(0, 5), squish))
  low_squish <- cdata(base + y_scale(c(0, 5), squish))
  .plot("test-scales.R: oob affects position values #6", base + y_scale(c(3, 7), squish))
  mid_squish <- cdata(base + y_scale(c(3, 7), squish))
})

