corpus_block("test-scales.R: scale_apply preserves class and attributes", {
  df <- data_frame(
      x = structure(c(1, 2), foo = "bar", class = c("baz", "numeric")),
      y = c(1, 1),
      z = c("A", "B")
    )
  `c.baz` <- function(...) {
      dots <- list(...)
      attris <- attributes(dots[[1]])
      x <- do.call("c", lapply(dots, unclass))
      attributes(x) <- attris
      x
    }
  `[.baz` <- function(x, i) {
      attris <- attributes(x)
      x <- unclass(x)[i]
      attributes(x) <- attris
      x
    }
  .plot("test-scales.R: scale_apply preserves class and attributes #1", plot <- ggplot(df, aes(x, y)) +
      scale_x_continuous() +
      # Facetting such that 2 x-scales will exist, i.e. `x` will be subsetted
      facet_grid(~ z, scales = "free_x"))
  plot <- ggplot_build(plot)
  out <- with_bindings(scale_apply(
      df, "x", "transform", 1:2, plot@layout$panel_scales_x
    )[[1]], `c.baz` = `c.baz`, `[.baz` = `[.baz`, .env = global_env())
  class(df$x) <- "foobar"
  out <- with_bindings(scale_apply(
      df, "x", "transform", 1:2, plot@layout$panel_scales_x
    )[[1]], `c.baz` = `c.baz`, `[.baz` = `[.baz`, .env = global_env())
})

